import os, signal

def read_cmdline(pid):
    try:
        with open(f'/proc/{pid}/cmdline','rb') as f:
            return f.read().decode('utf-8','ignore')
    except Exception:
        return ''

def read_ppid(pid):
    try:
        with open(f'/proc/{pid}/stat','r') as f:
            parts = f.read().split()
        return int(parts[3])
    except Exception:
        return None

# Find main pid
main_pid = None
for pid in os.listdir('/proc'):
    if not pid.isdigit():
        continue
    cmd = read_cmdline(pid)
    if 'import multiprocessing as mp' in cmd and 'PyCBC_T2_2.gwf' in cmd:
        main_pid = int(pid)
        break

print('main_pid', main_pid)
if main_pid is None:
    raise SystemExit(0)

# Build child map
ppid_map = {}
for pid in os.listdir('/proc'):
    if not pid.isdigit():
        continue
    ppid = read_ppid(pid)
    if ppid is None:
        continue
    ppid_map.setdefault(ppid, []).append(int(pid))

# Collect descendants
stack = [main_pid]
all_pids = set()
while stack:
    pid = stack.pop()
    if pid in all_pids:
        continue
    all_pids.add(pid)
    for child in ppid_map.get(pid, []):
        stack.append(child)

print('killing', len(all_pids), 'processes')
for pid in all_pids:
    try:
        os.kill(pid, signal.SIGTERM)
    except Exception as e:
        pass
